// 完整拥有值的比较保原Owner/预约/元数据及lot顺序，不把同品替代当作原货仍在。
bool owner(const Owner&a,const Owner&b){return owner_equal(a,b)&&a.extra==b.extra&&a.field_order==b.field_order;}
bool identity(const WorldIdentity&a,const WorldIdentity&b){return a.world_id==b.world_id&&a.execution_epoch==b.execution_epoch&&a.revision==b.revision&&a.tick==b.tick;}
bool lot(const LotView&a,const LotView&b){return a.id==b.id&&a.item_id==b.item_id&&a.quantity==b.quantity&&owner(a.owner,b.owner)&&a.reserved_by==b.reserved_by&&a.extra==b.extra&&a.field_order==b.field_order;}
bool inventory(const InventoryView&a,const InventoryView&b){if(a.id!=b.id||!owner(a.owner,b.owner)||a.capacity!=b.capacity||a.revision!=b.revision||a.field_order!=b.field_order||a.lots.size()!=b.lots.size())return false;for(std::size_t i=0;i<a.lots.size();++i)if(!lot(a.lots[i],b.lots[i]))return false;return true;}
bool wallet(const WalletView&a,const WalletView&b){if(a.id!=b.id||!owner(a.owner,b.owner)||a.balance!=b.balance||a.field_order!=b.field_order||a.reserved.size()!=b.reserved.size())return false;for(std::size_t i=0;i<a.reserved.size();++i)if(a.reserved[i].action_id!=b.reserved[i].action_id||a.reserved[i].amount!=b.reserved[i].amount)return false;return true;}
bool versions(const std::vector<ReadVersion>&a,const std::vector<ReadVersion>&b){if(a.size()!=b.size())return false;for(std::size_t i=0;i<a.size();++i)if(a[i].resource.kind!=b[i].resource.kind||a[i].resource.id!=b[i].resource.id||a[i].version!=b[i].version)return false;return true;}
// 目录只供原合同静态绑定，绝不拿当前在店位置/今日余额代替旧许可与成本。
bool declared(const PrivateShopCatalog& c,const PrivateShopRecord& shop){const auto* p=c.premises.find(shop.terms.premises_id);const auto&t=shop.terms;return c.version==1&&p&&p->id==t.premises_id&&p->place_id==t.place_id&&p->lessor_actor_id==t.lessor_actor_id&&p->lessor_wallet_id==t.lessor_wallet_id&&p->market_shop_id==t.market_shop_id&&p->opening_fee==t.opening_fee&&p->initial_capital==t.initial_capital&&p->inventory_capacity==t.inventory_capacity&&p->daily_rent==t.daily_rent&&p->rent_rate_profile==t.rent_rate_profile;}
// 只读本次Common已成功原语的实际完整单容器；新建/重复/额外容器不能冒原库存变更。
const ResourceInventoryExecutionDraft* one_inventory(const ResourceOperationExecutionDraft& op,const InventoryView& before){if(!op.wallets.empty()||op.inventories.size()!=1)return nullptr;const auto& v=op.inventories.front();return v.inventory_id==before.id&&v.before&&inventory(*v.before,before)?&v:nullptr;}
const LotView* find_lot(const InventoryView& in,const StableId& id){const LotView* found=nullptr;for(const auto& l:in.lots)if(l.id==id){if(found)return nullptr;found=&l;}return found;}
// 核原两腿和全部预约，仅改实际balance；收入/资本的业务意义由原具名关闭来源给定。
bool paid(const ResourceOperationExecutionDraft& op,const ResourceOperation& raw,const WalletView& before,const WalletView& after,Integer delta,bool spendable){const auto*p=std::get_if<WalletDelta>(&raw);if(!p||p->wallet_id!=before.id||p->delta!=delta||p->require_spendable!=spendable||op.wallets.size()!=1||!op.inventories.empty()||!op.lot_flows.empty())return false;const auto&f=op.wallets.front();auto expected=before;if(__builtin_add_overflow(before.balance,delta,&expected.balance)||expected.balance<0)return false;return f.wallet_id==before.id&&f.before&&wallet(*f.before,before)&&wallet(f.after,after)&&wallet(expected,after);}
// 入库映射只有原购入批整批Adjust掉，再原Add建一个新批；不允许原背包旧货偷换。
