 const auto fail=[&](const StableId&code)->Outcome<PrivateShopOriginalStockMovement>{return {false,{},common_failure(code,id).error};};const auto* f=x.shops.purchases.find(id);const auto serial=organization_instance_sequence(id,"private_shop_stock");Integer after_header=0,after_lot=0;if(!serial||__builtin_add_overflow(*serial,Integer{1},&after_header)||__builtin_add_overflow(after_header,Integer{1},&after_lot))return fail("PrivateShopStockingOriginalRequired");
 if(!f||f->id!=id||!serial||*serial!=b.next_instance_before||f->shop_id!=b.shop_before.id||f->market_shop_id!=b.shop_before.terms.market_shop_id||f->from_inventory_id!=b.bag_before.id||f->to_inventory_id!=b.stock_before.id||f->tick!=x.common.tick()||f->quantity<=0||f->purchase_cash<=0||f->purchased_lots.empty()||f->stocked_lots.size()!=1||recipe.recipe.operations.size()!=2||recipe.next_instance_before!=after_header||recipe.next_instance_after!=after_lot||recipe.operations[0].next_instance_after!=after_header||recipe.operations[1].next_instance_before!=after_header||x.common.state().next_instance_id!=recipe.next_instance_after||!versions(recipe.recipe.expected_versions,b.versions)||!x.growth)return fail("PrivateShopStockingOriginalRequired");
 const auto* trade=x.growth->life_activities.find(f->trade_fact_id);const auto* head=x.common.state().facts.find(f->trade_fact_id);const auto* action=x.common.action(f->trade_fact_id);const auto* terms=trade?std::get_if<TradeTerms>(&trade->terms):nullptr;const auto n=organization_instance_sequence(f->trade_fact_id,"action");const auto& order=x.common.state().facts.order();const auto source_at=std::find(order.begin(),order.end(),f->trade_fact_id),at=std::find(order.begin(),order.end(),id);
