 const auto* debit=std::get_if<AdjustLots>(&recipe.recipe.operations[0]);const auto* add=std::get_if<AddLot>(&recipe.recipe.operations[1]);const auto* bag=one_inventory(recipe.operations[0],b.bag_before);const auto* stock=one_inventory(recipe.operations[1],b.stock_before);const Owner who{Owner::Kind::actor,action->actor_id,{}};
 if(!debit||debit->inventory_id!=b.bag_before.id||!debit->bump_revision||debit->lots.size()!=f->purchased_lots.size()||!add||add->inventory_id!=b.stock_before.id||add->item_id!=f->item_id||add->quantity!=f->quantity||!owner_equal(add->owner,who)||!add->reservation.empty()||!bag||!stock||recipe.operations[0].lot_flows.size()!=debit->lots.size()||recipe.operations[1].lot_flows.size()!=1)return fail("PrivateShopStockingRecipeMismatch");
