 const auto fail=[&](const StableId&code)->Outcome<PrivateShopOriginalStockMovement>{return {false,{},common_failure(code,id).error};};const auto* shop=x.shops.shops.find(b.shop_before.id);const auto* head=x.common.state().facts.find(id);const auto& drafts=x.common.resource_execution_drafts();const auto* actor=x.common.actor(b.shop_before.terms.proprietor_actor_id);
